import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import "../App.css";

function RecentHistory() {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadHistory = async () => {
    try {
      const token = localStorage.getItem("gigora_access_token");

      const response = await fetch(
        "http://127.0.0.1:8000/api/history/",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await response.json();

      console.log("History API:", data);

      // Handle both possible response formats
      const historyData = Array.isArray(data)
        ? data
        : data.data || [];

      setHistory(historyData.slice(0, 3));
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadHistory();

    const refresh = () => loadHistory();

    window.addEventListener(
      "dashboard-update",
      refresh
    );

    return () =>
      window.removeEventListener(
        "dashboard-update",
        refresh
      );
  }, []);

  if (loading) {
    return <p>Loading recent history...</p>;
  }

  return (
    <div className="recent-history">
      <div className="recent-header">
        <h2>Recent Activity</h2>

        <Link to="/history">
          View All
        </Link>
      </div>

      {history.length === 0 ? (
        <p>No history available.</p>
      ) : (
        history.map((item) => (
          <div
            key={item.id}
            className="recent-card"
          >
            <div className="recent-top">
              <span className="badge">
                {(item.tool_name || "Unknown").toUpperCase()}
              </span>

              <span className="recent-date">
                {new Date(item.created_at).toLocaleString()}
              </span>
            </div>

            <p className="recent-preview">
              {item.output_data?.proposal?.slice(0, 120) ||
                item.output_data?.optimized_title ||
                item.output_data?.summary ||
                item.input_data?.job_post?.slice(0, 120) ||
                item.input_data?.description?.slice(0, 120) ||
                item.input_data?.profile?.slice(0, 120) ||
                "No preview available"}
              ...
            </p>
          </div>
        ))
      )}
    </div>
  );
}

export default RecentHistory;
